using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

Console.WriteLine("Research Agent Starting...");

// Configure the AI client with tool support
var openAiClient = new OpenAIClient(
    Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key");

IChatClient chatClient = openAiClient
    .GetChatClient("gpt-4o")
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Initialize the research tools
var researchTools = new ResearchTools();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

// Run the research agent loop
string topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";
Console.WriteLine($"\nResearching topic: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.
        Follow these steps:
        1. Search the web for information about the topic (perform 2-3 searches with different queries).
        2. Take notes on the key findings from each search.
        3. Review all your notes, then provide a comprehensive summary of your findings.
        Always use the tools available to you. Be thorough and cite sources when possible.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await chatClient.GetResponseAsync(messages, chatOptions);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

Console.WriteLine("\n=== Collected Notes ===\n");
foreach (var note in researchTools.Notes)
{
    Console.WriteLine($"• {note}");
}

// --- Tool Definitions ---

public class ResearchTools
{
    public List<string> Notes { get; } = [];

    [Description("Search the web for information on a given query. Returns relevant search results.")]
    public string SearchWeb([Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        // Simulated web search results for demonstration purposes.
        // In production, replace with a real search API (e.g., Bing Search API).
        return $"""
            Search results for "{query}":
            1. [Wikipedia] Overview article covering key concepts and history of {query}.
               Summary: Provides foundational information and references.
               URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
            2. [Research Journal] Recent peer-reviewed paper on {query} (2025).
               Summary: Discusses latest developments and future directions.
               URL: https://arxiv.org/search/?query={Uri.EscapeDataString(query)}
            3. [News] Recent news coverage about {query} from major outlets.
               Summary: Reports on breakthroughs and industry applications.
               URL: https://news.example.com/{Uri.EscapeDataString(query)}
            """;
    }

    [Description("Take a note to remember important information found during research.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({Notes.Count} total)");
        return $"Note saved successfully. You now have {Notes.Count} note(s).";
    }

    [Description("Retrieve all notes taken so far during the research.")]
    public string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes taken yet.";

        Console.WriteLine($"  [Tool] Retrieving {Notes.Count} note(s)");
        return string.Join("\n", Notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

